using System;namespace Exoduser.UnityPort.Core {public sealed class GateEnterDelay {public bool Pending{get;private set;}public bool Dissolving{get;private set;}public double Elapsed{get;private set;}public bool Ready=>Pending&&Elapsed>=1.1;public double SigilOpacity=>Dissolving?1-Ease(Elapsed/1.4):1;public double EnterOpacity(bool reduced)=>Dissolving?(reduced?0:1-Ease(Elapsed/1.1)):1;public double EnterShift(bool reduced)=>Dissolving&&!reduced?-5.6*Ease(Elapsed/1.1):0;public bool Begin(){if(Pending)return false;Pending=Dissolving=true;Elapsed=0;return true;}public void Tick(double delta){if(Dissolving&&delta>0&&!double.IsInfinity(delta)&&!double.IsNaN(delta))Elapsed+=delta;}public bool Consume(){if(!Ready)return false;Pending=false;return true;}public void Reset(){Pending=Dissolving=false;Elapsed=0;}static double Ease(double x){x=Math.Max(0,Math.Min(1,x));if(x==0||x==1)return x;double lo=0,hi=1;for(int i=0;i<24;i++){double t=(lo+hi)/2,u=1-t,bx=3*u*u*t*.25+3*u*t*t*.25+t*t*t;if(bx<x)lo=t;else hi=t;}double v=(lo+hi)/2,w=1-v;return 3*w*w*v*.1+3*w*v*v+v*v*v;}}}
